// src/components/AdminMessages/ChatArea.jsx
import { useState, useRef, useEffect } from 'react';
import { Send, Paperclip, Smile, MoreVertical } from 'lucide-react';

function ChatArea({ selectedConversation, messages, onSendMessage }) {
  const [newMessage, setNewMessage] = useState('');
  const [sending, setSending] = useState(false);

  const handleSendMessage = async (e) => {
    if (e) e.preventDefault();
    if (!newMessage.trim() || !selectedConversation) return;

    try {
      setSending(true);
      await onSendMessage(newMessage);
      setNewMessage('');
    } catch (error) {
      console.error('Erreur envoi message:', error);
    } finally {
      setSending(false);
    }
  };

  const currentUser = typeof window !== 'undefined' ? JSON.parse(localStorage.getItem('user') || 'null') : null;

  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Scroll to bottom when messages change
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  const formatTime = (timestamp) => {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  if (!selectedConversation) {
    return (
      <div className="lg:col-span-2 bg-white rounded-xl shadow-md border border-gray-200 flex flex-col">
        <div className="flex-1 flex items-center justify-center text-gray-500">
          <p>Sélectionnez une conversation pour commencer à discuter</p>
        </div>
      </div>
    );
  }

  return (
    <div className="lg:col-span-2 bg-white rounded-xl shadow-md border border-gray-200 flex flex-col">
      {/* En-tête de la conversation */}
      <div className="p-4 border-b border-gray-200">
        <div className="flex justify-between items-center">
          <div>
            <h3 className="font-semibold text-gray-900">
              {selectedConversation.first_name} {selectedConversation.last_name}
            </h3>
            <p className="text-sm text-gray-600">{selectedConversation.title}</p>
          </div>
          <button className="text-gray-400 hover:text-gray-600">
            <MoreVertical className="h-5 w-5" />
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 p-4 overflow-y-auto bg-gray-50">
        <div className="space-y-4">
          {messages.map((message) => (
            <div
              key={message.id}
              // Align messages based on whether the sender is the current user
              className={`flex ${message.sender_id === (currentUser?.id || selectedConversation.user_id) ? 'justify-end' : 'justify-start'}`}
            >
                <div
                className={`max-w-xs lg:max-w-md px-4 py-2 rounded-lg ${
                  message.sender_id === (currentUser?.id || selectedConversation.user_id)
                    ? 'bg-blue-600 text-white rounded-br-none'
                    : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'
                }`}
              >
                    <p className="text-sm flex items-center space-x-2">
                      {message.message_text}
                      {message.attachments && (
                        <span className="text-gray-400 ml-2"><Paperclip className="h-4 w-4" /></span>
                      )}
                    </p>
                <p className={`text-xs mt-1 ${
                  message.sender_id === (currentUser?.id || selectedConversation.user_id) ? 'text-blue-200' : 'text-gray-500'
                } text-right`}>
                  {formatTime(message.created_at)}
                </p>
              </div>
            </div>
          ))}

          {messages.length === 0 && (
            <div className="text-center text-gray-500 py-8">
              Aucun message dans cette conversation
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      {/* Input d'envoi */}
      <div className="p-4 border-t border-gray-200">
        <form onSubmit={handleSendMessage}>
          <div className="flex space-x-2">
            <button type="button" className="p-2 text-gray-400 hover:text-gray-600">
              <Paperclip className="h-5 w-5" />
            </button>
            <button type="button" className="p-2 text-gray-400 hover:text-gray-600">
              <Smile className="h-5 w-5" />
            </button>
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Tapez votre message..."
              className="flex-1 border border-gray-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              disabled={sending}
            />
            <button
              type="submit"
              disabled={!newMessage.trim() || sending}
              className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 transition duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Send className="h-5 w-5" />
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export default ChatArea;
